GUIDE.svgDiagrams["m07-deploy"] = "<svg viewBox=\"0 0 672 500\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-labelledby=\"m07-deploy-title m07-deploy-desc\" font-family=\"'Google Sans','Noto Sans Thai Looped','Sarabun','Segoe UI',system-ui,sans-serif\">\n<title id=\"m07-deploy-title\">วิธี deploy Lambda: .zip หรือ container image</title>\n<desc id=\"m07-deploy-desc\">Developer ส่งโค้ดขึ้น Lambda ได้สองทาง: บีบอัดเป็น .zip แล้วอัปโหลดตรงหรือพักที่ S3 ก่อน หรือ build เป็น Docker image แล้ว push ไป ECR ให้ Lambda ดึงไปรัน</desc>\n<defs>\n<marker id=\"m07-deploy-arrow\" markerWidth=\"8\" markerHeight=\"6\" refX=\"7\" refY=\"3\" orient=\"auto\"><polygon points=\"0 0, 8 3, 0 6\" fill=\"#5f5d57\"/></marker>\n</defs>\n<rect width=\"100%\" height=\"100%\" fill=\"#f6f5f1\"/>\n<!-- zones -->\n<rect x=\"40\" y=\"132\" width=\"284\" height=\"320\" rx=\"8\" fill=\"rgba(29,29,27,0.02)\" stroke=\"rgba(29,29,27,0.10)\" stroke-width=\"0.8\"/>\n<rect x=\"48\" y=\"136\" width=\"144\" height=\"16\" rx=\"2\" fill=\"#f6f5f1\"/>\n<text x=\"56\" y=\"148\" fill=\"#5f5d57\" font-size=\"12\" font-weight=\"600\">1 · .zip (≤ 250 MB*)</text>\n<rect x=\"348\" y=\"132\" width=\"284\" height=\"320\" rx=\"8\" fill=\"rgba(29,29,27,0.02)\" stroke=\"rgba(29,29,27,0.10)\" stroke-width=\"0.8\"/>\n<rect x=\"356\" y=\"136\" width=\"208\" height=\"16\" rx=\"2\" fill=\"#f6f5f1\"/>\n<text x=\"364\" y=\"148\" fill=\"#5f5d57\" font-size=\"12\" font-weight=\"600\">2 · container image (≤ 10 GB*)</text>\n<!-- connectors (before nodes) -->\n<path d=\"M304,96 V112 Q304,120 296,120 H284 Q276,120 276,128 V164\" fill=\"none\" stroke=\"#5f5d57\" stroke-width=\"1.2\" marker-end=\"url(#m07-deploy-arrow)\"/>\n<path d=\"M368,96 V112 Q368,120 376,120 H580 Q588,120 588,128 V164\" fill=\"none\" stroke=\"#5f5d57\" stroke-width=\"1.2\" marker-end=\"url(#m07-deploy-arrow)\"/>\n<path d=\"M112,220 V268\" fill=\"none\" stroke=\"#5f5d57\" stroke-width=\"1.2\" marker-end=\"url(#m07-deploy-arrow)\"/>\n<path d=\"M248,220 V380\" fill=\"none\" stroke=\"#5f5d57\" stroke-width=\"1.2\" marker-end=\"url(#m07-deploy-arrow)\"/>\n<path d=\"M112,324 V380\" fill=\"none\" stroke=\"#5f5d57\" stroke-width=\"1.2\" marker-end=\"url(#m07-deploy-arrow)\"/>\n<path d=\"M488,220 V268\" fill=\"none\" stroke=\"#5f5d57\" stroke-width=\"1.2\" marker-end=\"url(#m07-deploy-arrow)\"/>\n<path d=\"M488,324 V380\" fill=\"none\" stroke=\"#5f5d57\" stroke-width=\"1.2\" marker-end=\"url(#m07-deploy-arrow)\"/>\n<!-- connector labels -->\n<rect x=\"118\" y=\"232\" width=\"120\" height=\"16\" rx=\"2\" fill=\"#f6f5f1\"/>\n<text x=\"178\" y=\"244\" fill=\"#5f5d57\" font-size=\"12\" font-weight=\"500\" text-anchor=\"middle\">ไฟล์ใหญ่: ผ่าน S3</text>\n<rect x=\"130\" y=\"336\" width=\"104\" height=\"16\" rx=\"2\" fill=\"#f6f5f1\"/>\n<text x=\"182\" y=\"348\" fill=\"#5f5d57\" font-size=\"12\" font-weight=\"500\" text-anchor=\"middle\">ไฟล์เล็ก: ตรงเลย</text>\n<rect x=\"496\" y=\"236\" width=\"84\" height=\"16\" rx=\"2\" fill=\"#f6f5f1\"/>\n<text x=\"538\" y=\"248\" fill=\"#5f5d57\" font-size=\"12\" font-weight=\"500\" text-anchor=\"middle\" font-family=\"ui-monospace,'Cascadia Code',Consolas,monospace\">docker push</text>\n<rect x=\"496\" y=\"344\" width=\"108\" height=\"16\" rx=\"2\" fill=\"#f6f5f1\"/>\n<text x=\"550\" y=\"356\" fill=\"#5f5d57\" font-size=\"12\" font-weight=\"500\" text-anchor=\"middle\">ดึง image มารัน</text>\n<!-- nodes -->\n<rect x=\"256\" y=\"40\" width=\"160\" height=\"56\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"256\" y=\"40\" width=\"160\" height=\"56\" rx=\"6\" fill=\"rgba(95,93,87,0.10)\" stroke=\"#8a877f\" stroke-width=\"1\"/>\n<text x=\"336\" y=\"72\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">Developer</text>\n<rect x=\"60\" y=\"164\" width=\"240\" height=\"56\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"60\" y=\"164\" width=\"240\" height=\"56\" rx=\"6\" fill=\"#ffffff\" stroke=\"#1d1d1b\" stroke-width=\"1\"/>\n<text x=\"180\" y=\"196\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">บีบอัดโค้ด + library เป็น .zip</text>\n<rect x=\"60\" y=\"268\" width=\"104\" height=\"56\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"60\" y=\"268\" width=\"104\" height=\"56\" rx=\"6\" fill=\"rgba(29,29,27,0.05)\" stroke=\"#5f5d57\" stroke-width=\"1\"/>\n<text x=\"112\" y=\"292\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">Amazon S3</text>\n<text x=\"112\" y=\"310\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">พักไฟล์ใหญ่</text>\n<rect x=\"72\" y=\"380\" width=\"200\" height=\"56\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"72\" y=\"380\" width=\"200\" height=\"56\" rx=\"6\" fill=\"rgba(180,83,9,0.10)\" stroke=\"#b45309\" stroke-width=\"1\"/>\n<text x=\"172\" y=\"412\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">AWS Lambda</text>\n<rect x=\"368\" y=\"164\" width=\"240\" height=\"56\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"368\" y=\"164\" width=\"240\" height=\"56\" rx=\"6\" fill=\"#ffffff\" stroke=\"#1d1d1b\" stroke-width=\"1\"/>\n<text x=\"488\" y=\"188\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">Build เป็น Docker image</text>\n<text x=\"488\" y=\"206\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">จาก Dockerfile</text>\n<rect x=\"408\" y=\"268\" width=\"160\" height=\"56\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"408\" y=\"268\" width=\"160\" height=\"56\" rx=\"6\" fill=\"rgba(29,29,27,0.05)\" stroke=\"#5f5d57\" stroke-width=\"1\"/>\n<text x=\"488\" y=\"292\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">Amazon ECR</text>\n<text x=\"488\" y=\"310\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">เก็บ image</text>\n<rect x=\"412\" y=\"380\" width=\"152\" height=\"56\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"412\" y=\"380\" width=\"152\" height=\"56\" rx=\"6\" fill=\"rgba(180,83,9,0.10)\" stroke=\"#b45309\" stroke-width=\"1\"/>\n<text x=\"488\" y=\"412\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">AWS Lambda</text>\n</svg>";
GUIDE.svgDiagrams["m07-layers"] = "<svg viewBox=\"0 0 640 408\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-labelledby=\"m07-layers-title m07-layers-desc\" font-family=\"'Google Sans','Noto Sans Thai Looped','Sarabun','Segoe UI',system-ui,sans-serif\">\n<title id=\"m07-layers-title\">Lambda layer: แยกไลบรารีไว้ตรงกลาง</title>\n<desc id=\"m07-layers-desc\">เปรียบเทียบก่อนและหลังใช้ Lambda layer: ก่อนใช้ ทุก function แพ็กไลบรารีซ้ำจน .zip ใหญ่ หลังใช้ function เหลือแต่โค้ดและอ้างอิงไลบรารีจาก layer ที่กองไว้ตรงกลาง ตัวเลขขนาดเป็นตัวอย่างประกอบ</desc>\n<defs>\n<marker id=\"m07-layers-arrow\" markerWidth=\"8\" markerHeight=\"6\" refX=\"7\" refY=\"3\" orient=\"auto\"><polygon points=\"0 0, 8 3, 0 6\" fill=\"#5f5d57\"/></marker>\n</defs>\n<rect width=\"100%\" height=\"100%\" fill=\"#f6f5f1\"/>\n<!-- zones -->\n<rect x=\"40\" y=\"72\" width=\"272\" height=\"264\" rx=\"8\" fill=\"rgba(29,29,27,0.02)\" stroke=\"rgba(29,29,27,0.10)\" stroke-width=\"0.8\"/>\n<rect x=\"48\" y=\"76\" width=\"176\" height=\"16\" rx=\"2\" fill=\"#f6f5f1\"/>\n<text x=\"56\" y=\"88\" fill=\"#5f5d57\" font-size=\"12\" font-weight=\"600\">ก่อน: ไลบรารีซ้ำทุกตัว</text>\n<rect x=\"328\" y=\"72\" width=\"272\" height=\"264\" rx=\"8\" fill=\"rgba(29,29,27,0.02)\" stroke=\"rgba(29,29,27,0.10)\" stroke-width=\"0.8\"/>\n<rect x=\"336\" y=\"76\" width=\"148\" height=\"16\" rx=\"2\" fill=\"#f6f5f1\"/>\n<text x=\"344\" y=\"88\" fill=\"#5f5d57\" font-size=\"12\" font-weight=\"600\">หลัง: แชร์ผ่าน Layer</text>\n<!-- connectors: functions reference the layer -->\n<path d=\"M402,168 V192 Q402,200 410,200 H416 Q424,200 424,208 V248\" fill=\"none\" stroke=\"#5f5d57\" stroke-width=\"1.2\" stroke-dasharray=\"4,3\" marker-end=\"url(#m07-layers-arrow)\"/>\n<path d=\"M526,168 V192 Q526,200 518,200 H504 Q496,200 496,208 V248\" fill=\"none\" stroke=\"#5f5d57\" stroke-width=\"1.2\" stroke-dasharray=\"4,3\" marker-end=\"url(#m07-layers-arrow)\"/>\n<!-- before: every function carries the libraries -->\n<rect x=\"60\" y=\"128\" width=\"232\" height=\"64\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"60\" y=\"128\" width=\"232\" height=\"64\" rx=\"6\" fill=\"#ffffff\" stroke=\"#1d1d1b\" stroke-width=\"1\"/>\n<text x=\"176\" y=\"156\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">Function A · .zip 50 MB</text>\n<text x=\"176\" y=\"174\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">โค้ด 1 MB + ไลบรารี 49 MB</text>\n<rect x=\"60\" y=\"224\" width=\"232\" height=\"64\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"60\" y=\"224\" width=\"232\" height=\"64\" rx=\"6\" fill=\"#ffffff\" stroke=\"#1d1d1b\" stroke-width=\"1\"/>\n<text x=\"176\" y=\"252\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">Function B · .zip 50 MB</text>\n<text x=\"176\" y=\"270\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">โค้ด 1 MB + ไลบรารีชุดเดิมอีก 49 MB</text>\n<!-- after: tiny functions + one shared layer -->\n<rect x=\"348\" y=\"112\" width=\"108\" height=\"56\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"348\" y=\"112\" width=\"108\" height=\"56\" rx=\"6\" fill=\"#ffffff\" stroke=\"#1d1d1b\" stroke-width=\"1\"/>\n<text x=\"402\" y=\"136\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">Function A</text>\n<text x=\"402\" y=\"154\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">.zip 1 MB</text>\n<rect x=\"472\" y=\"112\" width=\"108\" height=\"56\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"472\" y=\"112\" width=\"108\" height=\"56\" rx=\"6\" fill=\"#ffffff\" stroke=\"#1d1d1b\" stroke-width=\"1\"/>\n<text x=\"526\" y=\"136\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">Function B</text>\n<text x=\"526\" y=\"154\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">.zip 1 MB</text>\n<rect x=\"372\" y=\"248\" width=\"176\" height=\"64\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"372\" y=\"248\" width=\"176\" height=\"64\" rx=\"6\" fill=\"rgba(180,83,9,0.10)\" stroke=\"#b45309\" stroke-width=\"1\"/>\n<text x=\"460\" y=\"276\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">Lambda Layer</text>\n<text x=\"460\" y=\"294\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">ไลบรารีทั้งหมด 49 MB</text>\n<!-- legend -->\n<line x1=\"40\" y1=\"356\" x2=\"600\" y2=\"356\" stroke=\"rgba(29,29,27,0.10)\" stroke-width=\"0.8\"/>\n<line x1=\"48\" y1=\"376\" x2=\"84\" y2=\"376\" stroke=\"#5f5d57\" stroke-width=\"1.2\" stroke-dasharray=\"4,3\"/>\n<text x=\"96\" y=\"380\" fill=\"#5f5d57\" font-size=\"12\">เส้นประ = function อ้างอิงไลบรารีจาก Layer (ขนาด MB เป็นตัวอย่างประกอบ)</text>\n</svg>";
GUIDE.svgDiagrams["m07-version-after"] = "<svg viewBox=\"0 0 600 380\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-labelledby=\"m07-version-after-title m07-version-after-desc\" font-family=\"'Google Sans','Noto Sans Thai Looped','Sarabun','Segoe UI',system-ui,sans-serif\">\n<title id=\"m07-version-after-title\">Version และ alias: หลังย้าย PROD ไป Version 2</title>\n<desc id=\"m07-version-after-desc\">เส้นเวลาเดิม แต่ทดสอบ Version 2 ผ่านแล้วจึงย้าย alias PROD ให้ชี้ไป Version 2 โดย Version 1 ยังอยู่ ย้ายกลับได้ทันทีถ้ามีปัญหา trigger ที่ชี้ alias ไม่ต้องแก้</desc>\n<defs>\n<marker id=\"m07-version-after-arrow\" markerWidth=\"8\" markerHeight=\"6\" refX=\"7\" refY=\"3\" orient=\"auto\"><polygon points=\"0 0, 8 3, 0 6\" fill=\"#5f5d57\"/></marker>\n<marker id=\"m07-version-after-arrow-accent\" markerWidth=\"8\" markerHeight=\"6\" refX=\"7\" refY=\"3\" orient=\"auto\"><polygon points=\"0 0, 8 3, 0 6\" fill=\"#b45309\"/></marker>\n</defs>\n<rect width=\"100%\" height=\"100%\" fill=\"#f6f5f1\"/>\n<!-- time rail: old on the left, new on the right -->\n<path d=\"M48,248 H548\" fill=\"none\" stroke=\"#5f5d57\" stroke-width=\"1.5\" marker-end=\"url(#m07-version-after-arrow)\"/>\n<!-- alias pointers: both now enter Version 2 at separate points -->\n<path d=\"M232,120 V160 Q232,168 240,168 H284 Q292,168 292,176 V236\" fill=\"none\" stroke=\"#b45309\" stroke-width=\"1.2\" stroke-dasharray=\"4,3\" marker-end=\"url(#m07-version-after-arrow-accent)\"/>\n<path d=\"M376,120 V160 Q376,168 368,168 H316 Q308,168 308,176 V236\" fill=\"none\" stroke=\"#5f5d57\" stroke-width=\"1.2\" stroke-dasharray=\"4,3\" marker-end=\"url(#m07-version-after-arrow)\"/>\n<!-- alias tags -->\n<rect x=\"164\" y=\"88\" width=\"136\" height=\"32\" rx=\"16\" fill=\"#f6f5f1\"/>\n<rect x=\"164\" y=\"88\" width=\"136\" height=\"32\" rx=\"16\" fill=\"rgba(180,83,9,0.10)\" stroke=\"#b45309\" stroke-width=\"1\"/>\n<text x=\"232\" y=\"108\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">PROD · ลูกค้าจริง</text>\n<rect x=\"308\" y=\"88\" width=\"136\" height=\"32\" rx=\"16\" fill=\"#f6f5f1\"/>\n<rect x=\"308\" y=\"88\" width=\"136\" height=\"32\" rx=\"16\" fill=\"#ffffff\" stroke=\"#1d1d1b\" stroke-width=\"1\"/>\n<text x=\"376\" y=\"108\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">TEST · ทีมทดสอบ</text>\n<!-- versions on the rail -->\n<circle cx=\"120\" cy=\"248\" r=\"14\" fill=\"#1d1d1b\" stroke=\"#1d1d1b\" stroke-width=\"1\"/>\n<circle cx=\"300\" cy=\"248\" r=\"14\" fill=\"#1d1d1b\" stroke=\"#1d1d1b\" stroke-width=\"1\"/>\n<circle cx=\"480\" cy=\"248\" r=\"14\" fill=\"#f6f5f1\" stroke=\"#1d1d1b\" stroke-width=\"1.5\" stroke-dasharray=\"4,3\"/>\n<text x=\"120\" y=\"288\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">Version 1</text>\n<text x=\"120\" y=\"306\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">แก้ไม่ได้ · ยังอยู่</text>\n<text x=\"300\" y=\"288\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">Version 2</text>\n<text x=\"300\" y=\"306\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">แก้ไม่ได้</text>\n<text x=\"480\" y=\"288\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">$LATEST</text>\n<text x=\"480\" y=\"306\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">ฉบับร่าง · นักพัฒนาแก้ที่นี่</text>\n<!-- legend -->\n<line x1=\"40\" y1=\"328\" x2=\"560\" y2=\"328\" stroke=\"rgba(29,29,27,0.10)\" stroke-width=\"0.8\"/>\n<rect x=\"48\" y=\"340\" width=\"28\" height=\"16\" rx=\"8\" fill=\"rgba(180,83,9,0.10)\" stroke=\"#b45309\" stroke-width=\"1\"/>\n<text x=\"84\" y=\"352\" fill=\"#5f5d57\" font-size=\"12\">Alias = ป้ายชี้</text>\n<circle cx=\"216\" cy=\"348\" r=\"6\" fill=\"#1d1d1b\"/>\n<text x=\"228\" y=\"352\" fill=\"#5f5d57\" font-size=\"12\">Version = snapshot</text>\n<circle cx=\"380\" cy=\"348\" r=\"6\" fill=\"#f6f5f1\" stroke=\"#1d1d1b\" stroke-width=\"1.2\" stroke-dasharray=\"3,2\"/>\n<text x=\"392\" y=\"352\" fill=\"#5f5d57\" font-size=\"12\">$LATEST = ฉบับร่าง</text>\n</svg>";
GUIDE.svgDiagrams["m07-version-before"] = "<svg viewBox=\"0 0 600 380\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-labelledby=\"m07-version-before-title m07-version-before-desc\" font-family=\"'Google Sans','Noto Sans Thai Looped','Sarabun','Segoe UI',system-ui,sans-serif\">\n<title id=\"m07-version-before-title\">Version และ alias: ก่อนย้าย PROD</title>\n<desc id=\"m07-version-before-desc\">เส้นเวลาของ Lambda: Version 1 และ Version 2 เรียงบนเส้นเดียวกัน ตามด้วย $LATEST ที่เป็นฉบับร่าง alias PROD ชี้ไป Version 1 สำหรับลูกค้าจริง และ alias TEST ชี้ไป Version 2 สำหรับทีมทดสอบ</desc>\n<defs>\n<marker id=\"m07-version-before-arrow\" markerWidth=\"8\" markerHeight=\"6\" refX=\"7\" refY=\"3\" orient=\"auto\"><polygon points=\"0 0, 8 3, 0 6\" fill=\"#5f5d57\"/></marker>\n<marker id=\"m07-version-before-arrow-accent\" markerWidth=\"8\" markerHeight=\"6\" refX=\"7\" refY=\"3\" orient=\"auto\"><polygon points=\"0 0, 8 3, 0 6\" fill=\"#b45309\"/></marker>\n</defs>\n<rect width=\"100%\" height=\"100%\" fill=\"#f6f5f1\"/>\n<!-- time rail: old on the left, new on the right -->\n<path d=\"M48,248 H548\" fill=\"none\" stroke=\"#5f5d57\" stroke-width=\"1.5\" marker-end=\"url(#m07-version-before-arrow)\"/>\n<!-- alias pointers -->\n<path d=\"M120,120 V234\" fill=\"none\" stroke=\"#b45309\" stroke-width=\"1.2\" stroke-dasharray=\"4,3\" marker-end=\"url(#m07-version-before-arrow-accent)\"/>\n<path d=\"M300,120 V234\" fill=\"none\" stroke=\"#5f5d57\" stroke-width=\"1.2\" stroke-dasharray=\"4,3\" marker-end=\"url(#m07-version-before-arrow)\"/>\n<!-- alias tags -->\n<rect x=\"52\" y=\"88\" width=\"136\" height=\"32\" rx=\"16\" fill=\"#f6f5f1\"/>\n<rect x=\"52\" y=\"88\" width=\"136\" height=\"32\" rx=\"16\" fill=\"rgba(180,83,9,0.10)\" stroke=\"#b45309\" stroke-width=\"1\"/>\n<text x=\"120\" y=\"108\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">PROD · ลูกค้าจริง</text>\n<rect x=\"232\" y=\"88\" width=\"136\" height=\"32\" rx=\"16\" fill=\"#f6f5f1\"/>\n<rect x=\"232\" y=\"88\" width=\"136\" height=\"32\" rx=\"16\" fill=\"#ffffff\" stroke=\"#1d1d1b\" stroke-width=\"1\"/>\n<text x=\"300\" y=\"108\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">TEST · ทีมทดสอบ</text>\n<!-- versions on the rail -->\n<circle cx=\"120\" cy=\"248\" r=\"14\" fill=\"#1d1d1b\" stroke=\"#1d1d1b\" stroke-width=\"1\"/>\n<circle cx=\"300\" cy=\"248\" r=\"14\" fill=\"#1d1d1b\" stroke=\"#1d1d1b\" stroke-width=\"1\"/>\n<circle cx=\"480\" cy=\"248\" r=\"14\" fill=\"#f6f5f1\" stroke=\"#1d1d1b\" stroke-width=\"1.5\" stroke-dasharray=\"4,3\"/>\n<text x=\"120\" y=\"288\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">Version 1</text>\n<text x=\"120\" y=\"306\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">แก้ไม่ได้</text>\n<text x=\"300\" y=\"288\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">Version 2</text>\n<text x=\"300\" y=\"306\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">แก้ไม่ได้</text>\n<text x=\"480\" y=\"288\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">$LATEST</text>\n<text x=\"480\" y=\"306\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">ฉบับร่าง · นักพัฒนาแก้ที่นี่</text>\n<!-- legend -->\n<line x1=\"40\" y1=\"328\" x2=\"560\" y2=\"328\" stroke=\"rgba(29,29,27,0.10)\" stroke-width=\"0.8\"/>\n<rect x=\"48\" y=\"340\" width=\"28\" height=\"16\" rx=\"8\" fill=\"rgba(180,83,9,0.10)\" stroke=\"#b45309\" stroke-width=\"1\"/>\n<text x=\"84\" y=\"352\" fill=\"#5f5d57\" font-size=\"12\">Alias = ป้ายชี้</text>\n<circle cx=\"216\" cy=\"348\" r=\"6\" fill=\"#1d1d1b\"/>\n<text x=\"228\" y=\"352\" fill=\"#5f5d57\" font-size=\"12\">Version = snapshot</text>\n<circle cx=\"380\" cy=\"348\" r=\"6\" fill=\"#f6f5f1\" stroke=\"#1d1d1b\" stroke-width=\"1.2\" stroke-dasharray=\"3,2\"/>\n<text x=\"392\" y=\"352\" fill=\"#5f5d57\" font-size=\"12\">$LATEST = ฉบับร่าง</text>\n</svg>";
GUIDE.svgDiagrams["m08-bluegreen"] = "<svg viewBox=\"0 0 720 524\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-labelledby=\"m08-bluegreen-title m08-bluegreen-desc\" font-family=\"'Google Sans','Noto Sans Thai Looped','Sarabun','Segoe UI',system-ui,sans-serif\">\n<title id=\"m08-bluegreen-title\">Blue/green บน Elastic Beanstalk</title>\n<desc id=\"m08-bluegreen-desc\">ขั้น 1 clone environment blue เป็น green ขั้น 2 deploy และทดสอบเวอร์ชันใหม่ในสภาพแวดล้อมใหม่ ขั้น 3 สลับ CNAME ของสอง environment ทำให้ URL หลัก myapp ชี้ไป green และ myapp_new ชี้ไป blue</desc>\n<defs>\n<marker id=\"m08-bluegreen-arrow\" markerWidth=\"8\" markerHeight=\"6\" refX=\"7\" refY=\"3\" orient=\"auto\"><polygon points=\"0 0, 8 3, 0 6\" fill=\"#5f5d57\"/></marker>\n<marker id=\"m08-bluegreen-arrow-acc\" markerWidth=\"8\" markerHeight=\"6\" refX=\"7\" refY=\"3\" orient=\"auto\"><polygon points=\"0 0, 8 3, 0 6\" fill=\"#b45309\"/></marker>\n<marker id=\"m08-bluegreen-arrow-blue\" markerWidth=\"8\" markerHeight=\"6\" refX=\"7\" refY=\"3\" orient=\"auto\"><polygon points=\"0 0, 8 3, 0 6\" fill=\"#2e5aa8\"/></marker>\n<marker id=\"m08-bluegreen-arrow-green\" markerWidth=\"8\" markerHeight=\"6\" refX=\"7\" refY=\"3\" orient=\"auto\"><polygon points=\"0 0, 8 3, 0 6\" fill=\"#15803d\"/></marker>\n<marker id=\"m08-bluegreen-arrow-red\" markerWidth=\"8\" markerHeight=\"6\" refX=\"7\" refY=\"3\" orient=\"auto\"><polygon points=\"0 0, 8 3, 0 6\" fill=\"#b91c1c\"/></marker>\n</defs>\n<rect width=\"100%\" height=\"100%\" fill=\"#f6f5f1\"/>\n<rect x=\"16\" y=\"56\" width=\"240\" height=\"56\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"16\" y=\"56\" width=\"240\" height=\"56\" rx=\"6\" fill=\"rgba(46,90,168,0.10)\" stroke=\"#2e5aa8\" stroke-width=\"1\"/>\n<text x=\"136\" y=\"79\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">Elastic Beanstalk environment</text>\n<text x=\"136\" y=\"97\" fill=\"#2e5aa8\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">(blue)</text>\n<rect x=\"464\" y=\"56\" width=\"240\" height=\"56\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"464\" y=\"56\" width=\"240\" height=\"56\" rx=\"6\" fill=\"rgba(21,128,61,0.10)\" stroke=\"#15803d\" stroke-width=\"1\"/>\n<text x=\"584\" y=\"79\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">Elastic Beanstalk environment</text>\n<text x=\"584\" y=\"97\" fill=\"#15803d\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">(green)</text>\n<path d=\"M256,84 L464,84\" fill=\"none\" stroke=\"#5f5d57\" stroke-width=\"1.2\" marker-end=\"url(#m08-bluegreen-arrow)\"/>\n<rect x=\"290\" y=\"60\" width=\"140\" height=\"16\" fill=\"#f6f5f1\"/>\n<text x=\"360\" y=\"72\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">1 · clone environment</text>\n<text x=\"704\" y=\"140\" fill=\"#1d1d1b\" font-size=\"12\" text-anchor=\"end\">2 · deploy และทดสอบเวอร์ชันใหม่ใน environment นี้</text>\n<rect x=\"16\" y=\"172\" width=\"688\" height=\"136\" rx=\"8\" fill=\"rgba(29,29,27,0.02)\" stroke=\"rgba(29,29,27,0.10)\" stroke-width=\"0.8\"/>\n<rect x=\"24\" y=\"176\" width=\"209\" height=\"16\" rx=\"2\" fill=\"#f6f5f1\"/>\n<text x=\"32\" y=\"188\" fill=\"#5f5d57\" font-size=\"12\" font-weight=\"600\">ก่อนสลับ: URL หลักชี้ blue</text>\n<rect x=\"32\" y=\"204\" width=\"316\" height=\"40\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"32\" y=\"204\" width=\"316\" height=\"40\" rx=\"6\" fill=\"#ffffff\" stroke=\"#1d1d1b\" stroke-width=\"1\"/>\n<text x=\"190\" y=\"228\" fill=\"#1d1d1b\" font-size=\"12\" text-anchor=\"middle\" font-family=\"ui-monospace,Consolas,monospace\" style=\"white-space:pre\" xml:space=\"preserve\">myapp.useast-1.elasticbeanstalk.com</text>\n<path d=\"M348,224 L412,224\" fill=\"none\" stroke=\"#b45309\" stroke-width=\"1.2\" marker-end=\"url(#m08-bluegreen-arrow-acc)\"/>\n<rect x=\"412\" y=\"204\" width=\"276\" height=\"40\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"412\" y=\"204\" width=\"276\" height=\"40\" rx=\"6\" fill=\"rgba(46,90,168,0.10)\" stroke=\"#2e5aa8\" stroke-width=\"1\"/>\n<text x=\"550\" y=\"228\" fill=\"#2e5aa8\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">environment (blue)</text>\n<rect x=\"32\" y=\"252\" width=\"316\" height=\"40\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"32\" y=\"252\" width=\"316\" height=\"40\" rx=\"6\" fill=\"#ffffff\" stroke=\"#1d1d1b\" stroke-width=\"1\"/>\n<text x=\"190\" y=\"276\" fill=\"#1d1d1b\" font-size=\"12\" text-anchor=\"middle\" font-family=\"ui-monospace,Consolas,monospace\" style=\"white-space:pre\" xml:space=\"preserve\">myapp_new.useast-1.elasticbeanstalk.com</text>\n<path d=\"M348,272 L412,272\" fill=\"none\" stroke=\"#5f5d57\" stroke-width=\"1.2\" marker-end=\"url(#m08-bluegreen-arrow)\"/>\n<rect x=\"412\" y=\"252\" width=\"276\" height=\"40\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"412\" y=\"252\" width=\"276\" height=\"40\" rx=\"6\" fill=\"rgba(21,128,61,0.10)\" stroke=\"#15803d\" stroke-width=\"1\"/>\n<text x=\"550\" y=\"276\" fill=\"#15803d\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">environment (green)</text>\n<rect x=\"16\" y=\"332\" width=\"688\" height=\"136\" rx=\"8\" fill=\"rgba(29,29,27,0.02)\" stroke=\"rgba(29,29,27,0.10)\" stroke-width=\"0.8\"/>\n<rect x=\"24\" y=\"336\" width=\"268\" height=\"16\" rx=\"2\" fill=\"#f6f5f1\"/>\n<text x=\"32\" y=\"348\" fill=\"#5f5d57\" font-size=\"12\" font-weight=\"600\">3 · สลับ CNAMEs: URL หลักชี้ green</text>\n<rect x=\"32\" y=\"364\" width=\"316\" height=\"40\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"32\" y=\"364\" width=\"316\" height=\"40\" rx=\"6\" fill=\"#ffffff\" stroke=\"#1d1d1b\" stroke-width=\"1\"/>\n<text x=\"190\" y=\"388\" fill=\"#1d1d1b\" font-size=\"12\" text-anchor=\"middle\" font-family=\"ui-monospace,Consolas,monospace\" style=\"white-space:pre\" xml:space=\"preserve\">myapp.useast-1.elasticbeanstalk.com</text>\n<path d=\"M348,384 L412,384\" fill=\"none\" stroke=\"#b45309\" stroke-width=\"1.2\" marker-end=\"url(#m08-bluegreen-arrow-acc)\"/>\n<rect x=\"412\" y=\"364\" width=\"276\" height=\"40\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"412\" y=\"364\" width=\"276\" height=\"40\" rx=\"6\" fill=\"rgba(21,128,61,0.10)\" stroke=\"#15803d\" stroke-width=\"1\"/>\n<text x=\"550\" y=\"388\" fill=\"#15803d\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">environment (green)</text>\n<rect x=\"32\" y=\"412\" width=\"316\" height=\"40\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"32\" y=\"412\" width=\"316\" height=\"40\" rx=\"6\" fill=\"#ffffff\" stroke=\"#1d1d1b\" stroke-width=\"1\"/>\n<text x=\"190\" y=\"436\" fill=\"#1d1d1b\" font-size=\"12\" text-anchor=\"middle\" font-family=\"ui-monospace,Consolas,monospace\" style=\"white-space:pre\" xml:space=\"preserve\">myapp_new.useast-1.elasticbeanstalk.com</text>\n<path d=\"M348,432 L412,432\" fill=\"none\" stroke=\"#5f5d57\" stroke-width=\"1.2\" marker-end=\"url(#m08-bluegreen-arrow)\"/>\n<rect x=\"412\" y=\"412\" width=\"276\" height=\"40\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"412\" y=\"412\" width=\"276\" height=\"40\" rx=\"6\" fill=\"rgba(46,90,168,0.10)\" stroke=\"#2e5aa8\" stroke-width=\"1\"/>\n<text x=\"550\" y=\"436\" fill=\"#2e5aa8\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">environment (blue)</text>\n<line x1=\"16\" y1=\"488\" x2=\"704\" y2=\"488\" stroke=\"rgba(29,29,27,0.10)\" stroke-width=\"0.8\"/>\n<text x=\"16\" y=\"508\" fill=\"#5f5d57\" font-size=\"12\">ลูกศรส้ม = URL หลัก (myapp...) ที่ผู้ใช้เข้า · น้ำเงิน / เขียว = environment ตามชื่อ · ตามสไลด์ Blue/green deployments</text>\n</svg>";
GUIDE.svgDiagrams["m08-choose"] = "<svg viewBox=\"0 0 720 460\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-labelledby=\"m08-choose-title m08-choose-desc\" font-family=\"'Google Sans','Noto Sans Thai Looped','Sarabun','Segoe UI',system-ui,sans-serif\">\n<title id=\"m08-choose-title\">เลือก service สำหรับ container</title>\n<desc id=\"m08-choose-desc\">ถ้าทีมเพิ่งเริ่มและอยากเริ่มเร็วให้ใช้ Elastic Beanstalk ถ้าใช้ Kubernetes อยู่แล้วให้ใช้ Amazon EKS ถ้าต้องการดูแล EC2 เองให้ใช้ ECS แบบ EC2 ไม่เช่นนั้นใช้ ECS แบบ Fargate</desc>\n<defs>\n<marker id=\"m08-choose-arrow\" markerWidth=\"8\" markerHeight=\"6\" refX=\"7\" refY=\"3\" orient=\"auto\"><polygon points=\"0 0, 8 3, 0 6\" fill=\"#5f5d57\"/></marker>\n<marker id=\"m08-choose-arrow-acc\" markerWidth=\"8\" markerHeight=\"6\" refX=\"7\" refY=\"3\" orient=\"auto\"><polygon points=\"0 0, 8 3, 0 6\" fill=\"#b45309\"/></marker>\n</defs>\n<rect width=\"100%\" height=\"100%\" fill=\"#f6f5f1\"/>\n<rect x=\"40\" y=\"16\" width=\"280\" height=\"36\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"40\" y=\"16\" width=\"280\" height=\"36\" rx=\"6\" fill=\"#ffffff\" stroke=\"#1d1d1b\" stroke-width=\"1\"/>\n<text x=\"180\" y=\"38\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">จะรัน container บน AWS ด้วยอะไรดี</text>\n<path d=\"M180,52 L180,72\" fill=\"none\" stroke=\"#5f5d57\" stroke-width=\"1.2\" marker-end=\"url(#m08-choose-arrow)\"/>\n<rect x=\"40\" y=\"72\" width=\"280\" height=\"56\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"40\" y=\"72\" width=\"280\" height=\"56\" rx=\"6\" fill=\"#ffffff\" stroke=\"#5f5d57\" stroke-width=\"1\"/>\n<text x=\"180\" y=\"95\" fill=\"#1d1d1b\" font-size=\"12\" text-anchor=\"middle\">ทีมเพิ่งเริ่ม ไม่ค่อยมีประสบการณ์</text>\n<text x=\"180\" y=\"113\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">และอยากเริ่มเร็ว?</text>\n<rect x=\"440\" y=\"76\" width=\"200\" height=\"48\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"440\" y=\"76\" width=\"200\" height=\"48\" rx=\"6\" fill=\"rgba(180,83,9,0.10)\" stroke=\"#b45309\" stroke-width=\"1\"/>\n<text x=\"540\" y=\"104\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">Elastic Beanstalk</text>\n<path d=\"M320,100 L440,100\" fill=\"none\" stroke=\"#5f5d57\" stroke-width=\"1.2\" marker-end=\"url(#m08-choose-arrow)\"/>\n<rect x=\"364\" y=\"76\" width=\"32\" height=\"16\" fill=\"#f6f5f1\"/>\n<text x=\"380\" y=\"88\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">ใช่</text>\n<path d=\"M180,128 L180,168\" fill=\"none\" stroke=\"#5f5d57\" stroke-width=\"1.2\" marker-end=\"url(#m08-choose-arrow)\"/>\n<rect x=\"190\" y=\"140\" width=\"32\" height=\"16\" fill=\"#f6f5f1\"/>\n<text x=\"206\" y=\"152\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">ไม่</text>\n<rect x=\"40\" y=\"168\" width=\"280\" height=\"56\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"40\" y=\"168\" width=\"280\" height=\"56\" rx=\"6\" fill=\"#ffffff\" stroke=\"#5f5d57\" stroke-width=\"1\"/>\n<text x=\"180\" y=\"191\" fill=\"#1d1d1b\" font-size=\"12\" text-anchor=\"middle\">ใช้ Kubernetes อยู่แล้ว</text>\n<text x=\"180\" y=\"209\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">และอยากได้แบบ managed?</text>\n<rect x=\"440\" y=\"172\" width=\"200\" height=\"48\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"440\" y=\"172\" width=\"200\" height=\"48\" rx=\"6\" fill=\"#ffffff\" stroke=\"#1d1d1b\" stroke-width=\"1\"/>\n<text x=\"540\" y=\"200\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">Amazon EKS</text>\n<path d=\"M320,196 L440,196\" fill=\"none\" stroke=\"#5f5d57\" stroke-width=\"1.2\" marker-end=\"url(#m08-choose-arrow)\"/>\n<rect x=\"364\" y=\"172\" width=\"32\" height=\"16\" fill=\"#f6f5f1\"/>\n<text x=\"380\" y=\"184\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">ใช่</text>\n<path d=\"M180,224 L180,264\" fill=\"none\" stroke=\"#5f5d57\" stroke-width=\"1.2\" marker-end=\"url(#m08-choose-arrow)\"/>\n<rect x=\"190\" y=\"236\" width=\"32\" height=\"16\" fill=\"#f6f5f1\"/>\n<text x=\"206\" y=\"248\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">ไม่</text>\n<rect x=\"40\" y=\"264\" width=\"280\" height=\"56\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"40\" y=\"264\" width=\"280\" height=\"56\" rx=\"6\" fill=\"#ffffff\" stroke=\"#5f5d57\" stroke-width=\"1\"/>\n<text x=\"180\" y=\"287\" fill=\"#1d1d1b\" font-size=\"12\" text-anchor=\"middle\">ต้องการดูแล EC2 เอง?</text>\n<text x=\"180\" y=\"305\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">(โหลดคาดการณ์ได้ / ประหยัด / compliance)</text>\n<rect x=\"440\" y=\"268\" width=\"200\" height=\"48\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"440\" y=\"268\" width=\"200\" height=\"48\" rx=\"6\" fill=\"#ffffff\" stroke=\"#1d1d1b\" stroke-width=\"1\"/>\n<text x=\"540\" y=\"296\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">ECS + EC2 launch type</text>\n<path d=\"M320,292 L440,292\" fill=\"none\" stroke=\"#5f5d57\" stroke-width=\"1.2\" marker-end=\"url(#m08-choose-arrow)\"/>\n<rect x=\"364\" y=\"268\" width=\"32\" height=\"16\" fill=\"#f6f5f1\"/>\n<text x=\"380\" y=\"280\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">ใช่</text>\n<path d=\"M180,320 L180,360\" fill=\"none\" stroke=\"#5f5d57\" stroke-width=\"1.2\" marker-end=\"url(#m08-choose-arrow)\"/>\n<rect x=\"190\" y=\"332\" width=\"32\" height=\"16\" fill=\"#f6f5f1\"/>\n<text x=\"206\" y=\"344\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">ไม่</text>\n<rect x=\"40\" y=\"360\" width=\"280\" height=\"48\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"40\" y=\"360\" width=\"280\" height=\"48\" rx=\"6\" fill=\"#ffffff\" stroke=\"#1d1d1b\" stroke-width=\"1\"/>\n<text x=\"180\" y=\"388\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">ECS + Fargate launch type</text>\n<line x1=\"16\" y1=\"428\" x2=\"704\" y2=\"428\" stroke=\"rgba(29,29,27,0.10)\" stroke-width=\"0.8\"/>\n<text x=\"16\" y=\"448\" fill=\"#5f5d57\" font-size=\"12\">ผังนี้เป็นข้อสรุปของผู้สรุปจากสไลด์ (ข้อสอบตัวอย่าง, Fargate/EC2, EKS) ไม่ใช่ผังในสไลด์</text>\n</svg>";
GUIDE.svgDiagrams["m08-cli-map"] = "<svg viewBox=\"0 0 720 412\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-labelledby=\"m08-cli-map-title m08-cli-map-desc\" font-family=\"'Google Sans','Noto Sans Thai Looped','Sarabun','Segoe UI',system-ui,sans-serif\">\n<title id=\"m08-cli-map-title\">แผนที่คำสั่ง Docker CLI</title>\n<desc id=\"m08-cli-map-desc\">build สร้าง image จาก Dockerfile, run สร้าง container จาก image, commit สร้าง image ใหม่จาก container, push ส่ง image ไป registry คำสั่ง images, tag, rmi ใช้กับ image และ ps, logs, port, inspect, exec, stop, start, rm, update ใช้กับ container</desc>\n<defs>\n<marker id=\"m08-cli-map-arrow\" markerWidth=\"8\" markerHeight=\"6\" refX=\"7\" refY=\"3\" orient=\"auto\"><polygon points=\"0 0, 8 3, 0 6\" fill=\"#5f5d57\"/></marker>\n<marker id=\"m08-cli-map-arrow-acc\" markerWidth=\"8\" markerHeight=\"6\" refX=\"7\" refY=\"3\" orient=\"auto\"><polygon points=\"0 0, 8 3, 0 6\" fill=\"#b45309\"/></marker>\n</defs>\n<rect width=\"100%\" height=\"100%\" fill=\"#f6f5f1\"/>\n<rect x=\"16\" y=\"96\" width=\"120\" height=\"48\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"16\" y=\"96\" width=\"120\" height=\"48\" rx=\"6\" fill=\"#ffffff\" stroke=\"#1d1d1b\" stroke-width=\"1\"/>\n<text x=\"76\" y=\"124\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">Dockerfile</text>\n<rect x=\"300\" y=\"96\" width=\"120\" height=\"48\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"300\" y=\"96\" width=\"120\" height=\"48\" rx=\"6\" fill=\"#ffffff\" stroke=\"#1d1d1b\" stroke-width=\"1\"/>\n<text x=\"360\" y=\"124\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">Image</text>\n<rect x=\"584\" y=\"96\" width=\"120\" height=\"48\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"584\" y=\"96\" width=\"120\" height=\"48\" rx=\"6\" fill=\"rgba(180,83,9,0.10)\" stroke=\"#b45309\" stroke-width=\"1\"/>\n<text x=\"644\" y=\"124\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">Container</text>\n<path d=\"M136,120 L300,120\" fill=\"none\" stroke=\"#5f5d57\" stroke-width=\"1.2\" marker-end=\"url(#m08-cli-map-arrow)\"/>\n<rect x=\"196\" y=\"96\" width=\"44\" height=\"16\" fill=\"#f6f5f1\"/>\n<text x=\"218\" y=\"108\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">build</text>\n<path d=\"M420,120 L584,120\" fill=\"none\" stroke=\"#5f5d57\" stroke-width=\"1.2\" marker-end=\"url(#m08-cli-map-arrow)\"/>\n<rect x=\"485\" y=\"96\" width=\"34\" height=\"16\" fill=\"#f6f5f1\"/>\n<text x=\"502\" y=\"108\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">run</text>\n<path d=\"M644,96 L644,72 Q644,64 636,64 L368,64 Q360,64 360,72 L360,96\" fill=\"none\" stroke=\"#5f5d57\" stroke-width=\"1.2\" marker-end=\"url(#m08-cli-map-arrow)\"/>\n<rect x=\"474\" y=\"44\" width=\"56\" height=\"16\" fill=\"#f6f5f1\"/>\n<text x=\"502\" y=\"56\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">commit</text>\n<rect x=\"300\" y=\"224\" width=\"120\" height=\"48\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"300\" y=\"224\" width=\"120\" height=\"48\" rx=\"6\" fill=\"rgba(29,29,27,0.05)\" stroke=\"#5f5d57\" stroke-width=\"1\"/>\n<text x=\"360\" y=\"252\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">Registry</text>\n<path d=\"M380,144 L380,224\" fill=\"none\" stroke=\"#5f5d57\" stroke-width=\"1.2\" marker-end=\"url(#m08-cli-map-arrow)\"/>\n<text x=\"392\" y=\"188\" fill=\"#1d1d1b\" font-size=\"12\">push</text>\n<rect x=\"16\" y=\"168\" width=\"240\" height=\"100\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"16\" y=\"168\" width=\"240\" height=\"100\" rx=\"6\" fill=\"#ffffff\" stroke=\"#1d1d1b\" stroke-width=\"1\"/>\n<text x=\"30\" y=\"190\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\">กับ image</text>\n<text x=\"30\" y=\"214\" font-size=\"12\"><tspan font-family=\"ui-monospace,Consolas,monospace\" fill=\"#1d1d1b\">images</tspan><tspan fill=\"#5f5d57\"> · ดูรายการ</tspan></text>\n<text x=\"30\" y=\"232\" font-size=\"12\"><tspan font-family=\"ui-monospace,Consolas,monospace\" fill=\"#1d1d1b\">tag</tspan><tspan fill=\"#5f5d57\"> · ติด tag</tspan></text>\n<text x=\"30\" y=\"250\" font-size=\"12\"><tspan font-family=\"ui-monospace,Consolas,monospace\" fill=\"#1d1d1b\">rmi</tspan><tspan fill=\"#5f5d57\"> · ลบ image</tspan></text>\n<path d=\"M320,144 L320,148 Q320,156 312,156 L244,156 Q236,156 236,164 L236,168\" fill=\"none\" stroke=\"#5f5d57\" stroke-width=\"1.2\" stroke-dasharray=\"4,3\" marker-end=\"url(#m08-cli-map-arrow)\"/>\n<rect x=\"464\" y=\"168\" width=\"240\" height=\"196\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"464\" y=\"168\" width=\"240\" height=\"196\" rx=\"6\" fill=\"#ffffff\" stroke=\"#1d1d1b\" stroke-width=\"1\"/>\n<text x=\"478\" y=\"190\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\">กับ container</text>\n<text x=\"478\" y=\"214\" font-size=\"12\"><tspan font-family=\"ui-monospace,Consolas,monospace\" fill=\"#1d1d1b\">ps</tspan><tspan fill=\"#5f5d57\"> · ดูตัวที่รันอยู่</tspan></text>\n<text x=\"478\" y=\"232\" font-size=\"12\"><tspan font-family=\"ui-monospace,Consolas,monospace\" fill=\"#1d1d1b\">logs</tspan><tspan fill=\"#5f5d57\"> · ดู log</tspan></text>\n<text x=\"478\" y=\"250\" font-size=\"12\"><tspan font-family=\"ui-monospace,Consolas,monospace\" fill=\"#1d1d1b\">port</tspan><tspan fill=\"#5f5d57\"> · ดู port mapping</tspan></text>\n<text x=\"478\" y=\"268\" font-size=\"12\"><tspan font-family=\"ui-monospace,Consolas,monospace\" fill=\"#1d1d1b\">inspect</tspan><tspan fill=\"#5f5d57\"> · ดูรายละเอียด</tspan></text>\n<text x=\"478\" y=\"286\" font-size=\"12\"><tspan font-family=\"ui-monospace,Consolas,monospace\" fill=\"#1d1d1b\">exec</tspan><tspan fill=\"#5f5d57\"> · รันคำสั่งใน container</tspan></text>\n<text x=\"478\" y=\"304\" font-size=\"12\"><tspan font-family=\"ui-monospace,Consolas,monospace\" fill=\"#1d1d1b\">stop / start</tspan><tspan fill=\"#5f5d57\"> · หยุด / เริ่ม</tspan></text>\n<text x=\"478\" y=\"322\" font-size=\"12\"><tspan font-family=\"ui-monospace,Consolas,monospace\" fill=\"#1d1d1b\">rm</tspan><tspan fill=\"#5f5d57\"> · ลบ container</tspan></text>\n<text x=\"478\" y=\"340\" font-size=\"12\"><tspan font-family=\"ui-monospace,Consolas,monospace\" fill=\"#1d1d1b\">update</tspan><tspan fill=\"#5f5d57\"> · แก้ config ขณะรัน</tspan></text>\n<path d=\"M644,144 L644,168\" fill=\"none\" stroke=\"#5f5d57\" stroke-width=\"1.2\" stroke-dasharray=\"4,3\" marker-end=\"url(#m08-cli-map-arrow)\"/>\n<line x1=\"16\" y1=\"380\" x2=\"704\" y2=\"380\" stroke=\"rgba(29,29,27,0.10)\" stroke-width=\"0.8\"/>\n<text x=\"16\" y=\"400\" fill=\"#5f5d57\" font-size=\"12\">คำสั่งครบ 16 ตัวจากสไลด์ build, run, push, commit อยู่บนลูกศร ส่วนที่เหลืออยู่ในกล่อง</text>\n</svg>";
GUIDE.svgDiagrams["m08-compute"] = "<svg viewBox=\"0 0 720 372\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-labelledby=\"m08-compute-title m08-compute-desc\" font-family=\"'Google Sans','Noto Sans Thai Looped','Sarabun','Segoe UI',system-ui,sans-serif\">\n<title id=\"m08-compute-title\">ECS cluster แบบ Fargate เทียบกับ EC2: ใครดูแลอะไร</title>\n<desc id=\"m08-compute-desc\">container instance 1 ถึง 3 รัน App และ Bins/libs บน Docker engine (หนึ่งตัวต่อ OS) และ VM guest OS ใน ECS cluster เมื่อใช้ Fargate คุณดูแลเฉพาะ container ส่วน Docker engine และ OS เป็นหน้าที่ของ AWS เมื่อใช้ EC2 คุณดูแลทั้งหมด</desc>\n<defs>\n<marker id=\"m08-compute-arrow\" markerWidth=\"8\" markerHeight=\"6\" refX=\"7\" refY=\"3\" orient=\"auto\"><polygon points=\"0 0, 8 3, 0 6\" fill=\"#5f5d57\"/></marker>\n<marker id=\"m08-compute-arrow-acc\" markerWidth=\"8\" markerHeight=\"6\" refX=\"7\" refY=\"3\" orient=\"auto\"><polygon points=\"0 0, 8 3, 0 6\" fill=\"#b45309\"/></marker>\n<marker id=\"m08-compute-arrow-blue\" markerWidth=\"8\" markerHeight=\"6\" refX=\"7\" refY=\"3\" orient=\"auto\"><polygon points=\"0 0, 8 3, 0 6\" fill=\"#2e5aa8\"/></marker>\n<marker id=\"m08-compute-arrow-green\" markerWidth=\"8\" markerHeight=\"6\" refX=\"7\" refY=\"3\" orient=\"auto\"><polygon points=\"0 0, 8 3, 0 6\" fill=\"#15803d\"/></marker>\n<marker id=\"m08-compute-arrow-red\" markerWidth=\"8\" markerHeight=\"6\" refX=\"7\" refY=\"3\" orient=\"auto\"><polygon points=\"0 0, 8 3, 0 6\" fill=\"#b91c1c\"/></marker>\n</defs>\n<rect width=\"100%\" height=\"100%\" fill=\"#f6f5f1\"/>\n<text x=\"16\" y=\"36\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\">ECS cluster แบบ Fargate</text>\n<text x=\"704\" y=\"36\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\" text-anchor=\"end\">ECS cluster แบบ EC2</text>\n<rect x=\"152\" y=\"52\" width=\"456\" height=\"164\" rx=\"8\" fill=\"rgba(29,29,27,0.02)\" stroke=\"rgba(29,29,27,0.10)\" stroke-width=\"0.8\"/>\n<rect x=\"160\" y=\"56\" width=\"90\" height=\"16\" rx=\"2\" fill=\"#f6f5f1\"/>\n<text x=\"168\" y=\"68\" fill=\"#5f5d57\" font-size=\"12\" font-weight=\"600\">Containers</text>\n<text x=\"232\" y=\"92\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">Container instance 1</text>\n<rect x=\"164\" y=\"104\" width=\"136\" height=\"44\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"164\" y=\"104\" width=\"136\" height=\"44\" rx=\"6\" fill=\"rgba(46,90,168,0.10)\" stroke=\"#2e5aa8\" stroke-width=\"1\"/>\n<text x=\"232\" y=\"130\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">App 1</text>\n<rect x=\"164\" y=\"156\" width=\"136\" height=\"44\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"164\" y=\"156\" width=\"136\" height=\"44\" rx=\"6\" fill=\"rgba(46,90,168,0.10)\" stroke=\"#2e5aa8\" stroke-width=\"1\"/>\n<text x=\"232\" y=\"182\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">Bins/libs</text>\n<text x=\"380\" y=\"92\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">Container instance 2</text>\n<rect x=\"312\" y=\"104\" width=\"136\" height=\"44\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"312\" y=\"104\" width=\"136\" height=\"44\" rx=\"6\" fill=\"rgba(46,90,168,0.10)\" stroke=\"#2e5aa8\" stroke-width=\"1\"/>\n<text x=\"380\" y=\"130\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">App 2</text>\n<rect x=\"312\" y=\"156\" width=\"136\" height=\"44\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"312\" y=\"156\" width=\"136\" height=\"44\" rx=\"6\" fill=\"rgba(46,90,168,0.10)\" stroke=\"#2e5aa8\" stroke-width=\"1\"/>\n<text x=\"380\" y=\"182\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">Bins/libs</text>\n<text x=\"528\" y=\"92\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">Container instance 3</text>\n<rect x=\"460\" y=\"104\" width=\"136\" height=\"44\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"460\" y=\"104\" width=\"136\" height=\"44\" rx=\"6\" fill=\"rgba(46,90,168,0.10)\" stroke=\"#2e5aa8\" stroke-width=\"1\"/>\n<text x=\"528\" y=\"130\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">App 3</text>\n<rect x=\"460\" y=\"156\" width=\"136\" height=\"44\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"460\" y=\"156\" width=\"136\" height=\"44\" rx=\"6\" fill=\"rgba(46,90,168,0.10)\" stroke=\"#2e5aa8\" stroke-width=\"1\"/>\n<text x=\"528\" y=\"182\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">Bins/libs</text>\n<rect x=\"164\" y=\"232\" width=\"432\" height=\"40\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"164\" y=\"232\" width=\"432\" height=\"40\" rx=\"6\" fill=\"rgba(180,83,9,0.10)\" stroke=\"#b45309\" stroke-width=\"1\"/>\n<text x=\"380\" y=\"256\" fill=\"#1d1d1b\" font-size=\"12\" text-anchor=\"middle\">Docker engines (หนึ่งตัวต่อ OS ใน cluster)</text>\n<rect x=\"164\" y=\"280\" width=\"432\" height=\"40\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"164\" y=\"280\" width=\"432\" height=\"40\" rx=\"6\" fill=\"rgba(180,83,9,0.10)\" stroke=\"#b45309\" stroke-width=\"1\"/>\n<text x=\"380\" y=\"304\" fill=\"#1d1d1b\" font-size=\"12\" text-anchor=\"middle\">VM guest operating systems ใน ECS cluster</text>\n<path d=\"M146,104 H140 V200 H146\" fill=\"none\" stroke=\"#2e5aa8\" stroke-width=\"1.5\"/>\n<text x=\"130\" y=\"156\" fill=\"#2e5aa8\" font-size=\"12\" font-weight=\"600\" text-anchor=\"end\">คุณดูแล</text>\n<path d=\"M146,232 H140 V320 H146\" fill=\"none\" stroke=\"#b45309\" stroke-width=\"1.5\"/>\n<text x=\"130\" y=\"280\" fill=\"#b45309\" font-size=\"12\" font-weight=\"600\" text-anchor=\"end\">AWS ดูแล</text>\n<path d=\"M614,104 H620 V320 H614\" fill=\"none\" stroke=\"#2e5aa8\" stroke-width=\"1.5\"/>\n<text x=\"632\" y=\"208\" fill=\"#2e5aa8\" font-size=\"12\" font-weight=\"600\">คุณดูแล</text>\n<text x=\"632\" y=\"226\" fill=\"#2e5aa8\" font-size=\"12\" font-weight=\"600\">ทั้งหมด</text>\n<line x1=\"16\" y1=\"340\" x2=\"704\" y2=\"340\" stroke=\"rgba(29,29,27,0.10)\" stroke-width=\"0.8\"/>\n<text x=\"16\" y=\"360\" fill=\"#5f5d57\" font-size=\"12\">น้ำเงิน = คุณดูแลเอง · ส้ม = AWS ดูแลให้เมื่อใช้ Fargate (ถ้าใช้ EC2 ส่วนสีส้มนี้คุณดูแลเอง)</text>\n</svg>";
GUIDE.svgDiagrams["m08-deploy-policies"] = "<svg viewBox=\"0 0 720 380\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" aria-labelledby=\"m08-deploy-policies-title m08-deploy-policies-desc\" font-family=\"'Google Sans','Noto Sans Thai Looped','Sarabun','Segoe UI',system-ui,sans-serif\">\n<title id=\"m08-deploy-policies-title\">Deployment policy ของ Elastic Beanstalk 5 แบบ</title>\n<desc id=\"m08-deploy-policies-desc\">เรียงจาก All at once ที่เร็วที่สุดแต่มี downtime ไปจนถึง Traffic splitting ที่ใช้ทำ canary testing: Rolling, Rolling with batch และ Immutable อยู่ตรงกลาง ยิ่งยอมให้มี downtime ยิ่ง deploy ได้เร็ว</desc>\n<defs>\n<marker id=\"m08-deploy-policies-arrow\" markerWidth=\"8\" markerHeight=\"6\" refX=\"7\" refY=\"3\" orient=\"auto\"><polygon points=\"0 0, 8 3, 0 6\" fill=\"#5f5d57\"/></marker>\n<marker id=\"m08-deploy-policies-arrow-acc\" markerWidth=\"8\" markerHeight=\"6\" refX=\"7\" refY=\"3\" orient=\"auto\"><polygon points=\"0 0, 8 3, 0 6\" fill=\"#b45309\"/></marker>\n<marker id=\"m08-deploy-policies-arrow-blue\" markerWidth=\"8\" markerHeight=\"6\" refX=\"7\" refY=\"3\" orient=\"auto\"><polygon points=\"0 0, 8 3, 0 6\" fill=\"#2e5aa8\"/></marker>\n<marker id=\"m08-deploy-policies-arrow-green\" markerWidth=\"8\" markerHeight=\"6\" refX=\"7\" refY=\"3\" orient=\"auto\"><polygon points=\"0 0, 8 3, 0 6\" fill=\"#15803d\"/></marker>\n<marker id=\"m08-deploy-policies-arrow-red\" markerWidth=\"8\" markerHeight=\"6\" refX=\"7\" refY=\"3\" orient=\"auto\"><polygon points=\"0 0, 8 3, 0 6\" fill=\"#b91c1c\"/></marker>\n</defs>\n<rect width=\"100%\" height=\"100%\" fill=\"#f6f5f1\"/>\n<line x1=\"16\" y1=\"64\" x2=\"700\" y2=\"64\" stroke=\"#5f5d57\" stroke-width=\"1.2\" marker-end=\"url(#m08-deploy-policies-arrow)\"/>\n<text x=\"16\" y=\"48\" fill=\"#b91c1c\" font-size=\"12\" font-weight=\"600\">เร็วกว่า · downtime มากกว่า</text>\n<text x=\"704\" y=\"48\" fill=\"#15803d\" font-size=\"12\" font-weight=\"600\" text-anchor=\"end\">ช้ากว่า · ปลอดภัยกว่า</text>\n<rect x=\"16\" y=\"88\" width=\"128\" height=\"120\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"16\" y=\"88\" width=\"128\" height=\"120\" rx=\"6\" fill=\"rgba(185,28,28,0.09)\" stroke=\"#b91c1c\" stroke-width=\"1\"/>\n<text x=\"80\" y=\"125\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">All at once</text>\n<text x=\"80\" y=\"143\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">ทุก instance พร้อมกัน</text>\n<text x=\"80\" y=\"161\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">เร็วที่สุด</text>\n<text x=\"80\" y=\"179\" fill=\"#b91c1c\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">มี downtime</text>\n<rect x=\"156\" y=\"88\" width=\"128\" height=\"120\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"156\" y=\"88\" width=\"128\" height=\"120\" rx=\"6\" fill=\"#ffffff\" stroke=\"#1d1d1b\" stroke-width=\"1\"/>\n<text x=\"220\" y=\"125\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">Rolling</text>\n<text x=\"220\" y=\"143\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">ทีละ batch</text>\n<text x=\"220\" y=\"161\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">ไม่ downtime</text>\n<text x=\"220\" y=\"179\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">capacity ลดชั่วคราว</text>\n<rect x=\"296\" y=\"88\" width=\"128\" height=\"120\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"296\" y=\"88\" width=\"128\" height=\"120\" rx=\"6\" fill=\"#ffffff\" stroke=\"#1d1d1b\" stroke-width=\"1\"/>\n<text x=\"360\" y=\"125\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">Rolling with batch</text>\n<text x=\"360\" y=\"143\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">เพิ่ม batch ใหม่ก่อน</text>\n<text x=\"360\" y=\"161\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">ไม่เสีย capacity</text>\n<text x=\"360\" y=\"179\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">นานกว่า rolling</text>\n<rect x=\"436\" y=\"88\" width=\"128\" height=\"120\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"436\" y=\"88\" width=\"128\" height=\"120\" rx=\"6\" fill=\"rgba(21,128,61,0.10)\" stroke=\"#15803d\" stroke-width=\"1\"/>\n<text x=\"500\" y=\"125\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">Immutable</text>\n<text x=\"500\" y=\"143\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">instance ใหม่ทั้งชุด</text>\n<text x=\"500\" y=\"161\" fill=\"#15803d\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">rollback ปลอดภัย</text>\n<text x=\"500\" y=\"179\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">ใช้เวลานาน</text>\n<rect x=\"576\" y=\"88\" width=\"128\" height=\"120\" rx=\"6\" fill=\"#f6f5f1\"/>\n<rect x=\"576\" y=\"88\" width=\"128\" height=\"120\" rx=\"6\" fill=\"rgba(21,128,61,0.10)\" stroke=\"#15803d\" stroke-width=\"1\"/>\n<text x=\"640\" y=\"125\" fill=\"#1d1d1b\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">Traffic splitting</text>\n<text x=\"640\" y=\"143\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">เหมือน immutable</text>\n<text x=\"640\" y=\"161\" fill=\"#5f5d57\" font-size=\"12\" text-anchor=\"middle\">ส่ง traffic บางส่วน</text>\n<text x=\"640\" y=\"179\" fill=\"#15803d\" font-size=\"12\" font-weight=\"600\" text-anchor=\"middle\">ใช้ทำ canary</text>\n<rect x=\"16\" y=\"228\" width=\"688\" height=\"68\" rx=\"6\" fill=\"rgba(180,83,9,0.10)\"/>\n<rect x=\"16\" y=\"228\" width=\"4\" height=\"68\" fill=\"#b45309\"/>\n<text x=\"34\" y=\"252\" fill=\"#b45309\" font-size=\"12\" font-weight=\"600\">ข้อแลกเปลี่ยนหลัก: ยิ่งยอมให้มี downtime ยิ่ง deploy ได้เร็ว</text>\n<text x=\"34\" y=\"272\" fill=\"#1d1d1b\" font-size=\"12\">ยอมหยุดได้ → All at once (เร็วที่สุด) · ไม่อยากหยุด → Rolling ไปจนถึง Immutable / Traffic splitting ซึ่งใช้เวลานานขึ้น</text>\n<text x=\"16\" y=\"324\" fill=\"#5f5d57\" font-size=\"12\">Blue/green ทำแยกต่างหาก (clone environment แล้วสลับ CNAME) ดูหัวข้อถัดไป</text>\n<line x1=\"16\" y1=\"340\" x2=\"704\" y2=\"340\" stroke=\"rgba(29,29,27,0.10)\" stroke-width=\"0.8\"/>\n<text x=\"16\" y=\"360\" fill=\"#5f5d57\" font-size=\"12\">แดง = มี downtime · เทา = ไม่ downtime แต่ capacity ลดหรือใช้เวลานาน · เขียว = rollback ปลอดภัย ไม่สะดุด</text>\n</svg>";
